import json

with open('baseline-packages.json') as f:
    baseline = json.load(f)
with open('after-cpm-packages.json') as f:
    after = json.load(f)

def build_lookup(data):
    lookup = {}
    for proj in data['projects']:
        name = proj['path'].split('/')[-1]
        for fw in proj['frameworks']:
            for pkg in fw['topLevelPackages']:
                key = (name, fw['framework'], pkg['id'])
                lookup[key] = pkg['resolvedVersion']
    return lookup

b = build_lookup(baseline)
a = build_lookup(after)

all_keys = sorted(set(b.keys()) | set(a.keys()))
changes = []
unchanged = []
for k in all_keys:
    bv = b.get(k)
    av = a.get(k)
    if bv != av:
        changes.append(k + (bv or 'N/A', av or 'N/A'))
    else:
        unchanged.append(k + (bv,))

print('=== CHANGES ===')
if not changes:
    print('(none)')
for c in changes:
    print(f'  {c[0]:15s} {c[1]:8s} {c[2]:50s} {c[3]:10s} -> {c[4]}')

print()
print('=== UNCHANGED ===')
for u in unchanged:
    print(f'  {u[0]:15s} {u[1]:8s} {u[2]:50s} {u[3]}')
"", "description": "Compare baseline vs after-cpm"}
